contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint lockTime, uint minSum, uint amount) public payable {
        require(amount > 0);
        require(amount <= msg.value);

        c.SetMinSum(minSum);
        c.SetLogFile(address(0));
        c.Initialized();

        c.Put{value: amount}(lockTime);

        (uint unlockTime, uint balanceBefore) = c.Acc(address(this));

        uint cBalanceBefore = address(c).balance;
        uint testBalanceBefore = address(this).balance;

        bool reverted;
        try c.Collect(amount) { reverted = false; } catch { reverted = true; }

        (, uint balanceAfter) = c.Acc(address(this));
        uint cBalanceAfter = address(c).balance;
        uint testBalanceAfter = address(this).balance;

        if (!reverted) {
            assert(balanceAfter == balanceBefore - amount);
            assert(cBalanceAfter == cBalanceBefore - amount);
            assert(testBalanceAfter == testBalanceBefore + amount);
        } else {
            assert(balanceAfter == balanceBefore);
            assert(cBalanceAfter == cBalanceBefore);
            assert(testBalanceAfter == testBalanceBefore);
        }
    }

    receive() external payable {}
}

