        require(address(this).balance >= amount);

        // Setup: give the caller some balance with a Put (amount is small enough not to overflow).
        c.Put{value: amount}(lockTime);

        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBalance = address(c).balance;

        // Try to collect more than the balance so the call must revert inside c.
        uint tooMuch = beforeBalance + 1;
        bool reverted;
        try c.Collect(tooMuch) { reverted = false; } catch { reverted = true; }

        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        assert(reverted && afterBalance == beforeBalance && address(c).balance == beforeContractBalance);
    }

    receive() external payable {}
}

