        c.Initialized();
        c.Put{value: amount}(lockTime);

        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(address(this));
        require(balanceBefore >= amount);

        bool enoughForCollect = balanceBefore >= minSum && block.timestamp > unlockTimeBefore;

        (bool sent, ) = address(this).call{value: 0}('');
        require(sent);

        bool collected;
        if (enoughForCollect) {
            c.Collect(amount);
            collected = true;
        } else {
            collected = false;
        }

        (uint unlockTimeAfter, uint balanceAfter) = c.Acc(address(this));

        assert(!collected || balanceAfter == balanceBefore - amount);
    }

    receive() external payable {}
}

